-- ═══ institutions — publish the 365 universities outside the TRNC (generated) ═══════
--
-- Generated by scripts/gen-institution-seeds.mjs --activate from data/institutions/*.csv.
-- TR 202 · CY 12 · GB 151. Matched BY ID (the seeds' UUIDv5s): only rows the seeds
-- created, never one added by hand later. From this file on, every one is in the Student Hub
-- directory and the pickers, and has a student list (20261095).
--
-- RE-RUN: a no-op against its own end state. It does NOT re-activate a row someone
-- deactivated after it ran — it refuses instead, naming the rows.
--
-- EXECUTION: supabase-migrate workflow (dry, then -f apply=true). Requires the three seeds.

SET ROLE postgres;

BEGIN;

DO $$
DECLARE v_n int;
BEGIN
  SELECT count(*) INTO v_n FROM public.institutions WHERE country = 'TR';
  IF v_n <> 202 THEN
    RAISE EXCEPTION 'REFUSING: TR holds % rows, its seed has 202. Apply the seed first. Nothing applied.', v_n;
  END IF;
  SELECT count(*) INTO v_n FROM public.institutions WHERE country = 'CY';
  IF v_n <> 12 THEN
    RAISE EXCEPTION 'REFUSING: CY holds % rows, its seed has 12. Apply the seed first. Nothing applied.', v_n;
  END IF;
  SELECT count(*) INTO v_n FROM public.institutions WHERE country = 'GB';
  IF v_n <> 151 THEN
    RAISE EXCEPTION 'REFUSING: GB holds % rows, its seed has 151. Apply the seed first. Nothing applied.', v_n;
  END IF;
  IF EXISTS (SELECT 1 FROM public.schema_migrations_applied WHERE filename = '20261099_institutions_activate_intl.sql') THEN
    SELECT count(*) INTO v_n FROM public.institutions WHERE country IN ('TR', 'CY', 'GB') AND NOT is_active;
    IF v_n > 0 THEN
      RAISE EXCEPTION 'REFUSING: % row(s) were deactivated after this file ran; re-running would undo that. Nothing applied.', v_n;
    END IF;
  END IF;
END $$;

