DO $$
DECLARE v_rows text;
BEGIN
  SELECT string_agg(format('%s %s/%s', coalesce(country, 'Other'), a, n), ' · ' ORDER BY country)
    INTO v_rows
    FROM (SELECT country, count(*) FILTER (WHERE is_active) a, count(*) n FROM public.institutions GROUP BY 1) x;
  RAISE NOTICE 'active/total per country: %', v_rows;
  IF (SELECT count(*) FROM public.institutions WHERE country = 'TR' AND is_active) <> 202 THEN
    RAISE EXCEPTION 'TR: not all 202 active. Nothing applied.';
  END IF;
  IF (SELECT count(*) FROM public.institutions WHERE country = 'CY' AND is_active) <> 12 THEN
    RAISE EXCEPTION 'CY: not all 12 active. Nothing applied.';
  END IF;
  IF (SELECT count(*) FROM public.institutions WHERE country = 'GB' AND is_active) <> 151 THEN
    RAISE EXCEPTION 'GB: not all 151 active. Nothing applied.';
  END IF;
  IF (SELECT count(*) FROM public.institutions WHERE country = 'XN' AND is_active) <> 23 THEN
    RAISE EXCEPTION 'the TRNC rows changed (expected 23 active). Nothing applied.';
  END IF;
END $$;

